"""Employee chat endpoints (mounted under /api/chat). Contract: docs/chat-api-contract.md."""

import logging

from fastapi import APIRouter, Depends, HTTPException, Request, Response, status
from fastapi.responses import JSONResponse
from sqlalchemy.exc import SQLAlchemyError
from sqlalchemy.orm import Session

from app.api.deps import get_llm_provider, get_submission_adapter
from app.auth.dependencies import require_roles
from app.chat.actions import StaleCardError
from app.chat.service import ChatService, ConversationConflict, ConversationNotFound
from app.db.models import User
from app.db.session import get_db
from app.domain.enums import UserRole
from app.integrations.base import SubmissionAdapter
from app.llm.base import LLMProvider
from app.schemas.chat import (
    ActionBody,
    ConversationDetail,
    ConversationList,
    ConversationSummary,
    MessageBody,
    TurnResponse,
)
from app.services.attachments import AttachmentError

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/chat", tags=["chat"])
Employee = Depends(require_roles(UserRole.EMPLOYEE))


def get_chat_service(
    request: Request,
    db: Session = Depends(get_db),
    user: User = Employee,
    llm: LLMProvider = Depends(get_llm_provider),
    adapter: SubmissionAdapter = Depends(get_submission_adapter),
) -> ChatService:
    return ChatService(db, user, llm, adapter, request.app.state.settings)


def _not_found() -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Conversation not found")


def _db_unavailable() -> JSONResponse:
    return JSONResponse(
        status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
        content={"detail": "The database is temporarily unavailable. Please try again."},
    )


@router.get("/conversations", response_model=ConversationList)
def list_conversations(service: ChatService = Depends(get_chat_service)) -> ConversationList:
    return ConversationList(items=service.list_conversations())


@router.post(
    "/conversations", response_model=ConversationSummary, status_code=status.HTTP_201_CREATED
)
def create_conversation(service: ChatService = Depends(get_chat_service)) -> ConversationSummary:
    return service.create_conversation()


@router.get("/conversations/{conversation_id}", response_model=ConversationDetail)
def get_conversation(
    conversation_id: int, service: ChatService = Depends(get_chat_service)
) -> ConversationDetail:
    try:
        return service.get_conversation(conversation_id)
    except ConversationNotFound:
        raise _not_found() from None


@router.post("/conversations/{conversation_id}/messages", response_model=TurnResponse)
def post_message(
    conversation_id: int,
    body: MessageBody,
    request: Request,
    service: ChatService = Depends(get_chat_service),
) -> Response | TurnResponse:
    limit = request.app.state.settings.chat_max_message_chars
    if len(body.content) > limit:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,
            detail=f"Message is too long (maximum {limit} characters).",
        )
    max_files = request.app.state.settings.max_attachments_per_message
    if len(body.attachment_ids) > max_files:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,
            detail=f"At most {max_files} files can be sent with one message.",
        )
    if not body.content.strip() and not body.attachment_ids:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail="Message must not be blank."
        )
    try:
        return service.post_message(conversation_id, body.content, body.attachment_ids)
    except ConversationNotFound:
        raise _not_found() from None
    except AttachmentError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail) from None
    except ConversationConflict:
        return JSONResponse(
            status_code=status.HTTP_409_CONFLICT,
            content={"detail": "The conversation changed while I was working. Please try again."},
        )
    except SQLAlchemyError:
        logger.exception("Database error while handling a chat message")
        return _db_unavailable()


@router.post("/conversations/{conversation_id}/actions", response_model=TurnResponse)
def post_action(
    conversation_id: int,
    body: ActionBody,
    service: ChatService = Depends(get_chat_service),
) -> Response | TurnResponse:
    try:
        return service.post_action(conversation_id, body.card_id, body.action)
    except ConversationNotFound:
        raise _not_found() from None
    except StaleCardError as exc:
        return JSONResponse(
            status_code=status.HTTP_409_CONFLICT,
            content={"detail": str(exc), "warning_code": "stale_card"},
        )
    except SQLAlchemyError:
        logger.exception("Database error while handling a card action")
        return _db_unavailable()
"""Approver endpoints (mounted under /api/approvals). Contract:
docs/phase3-approval-design.md, section 5.

* HR approvers work the leave queue and the Finance approver the claim queue, each limited to
  the requests assigned to them; other users get 403.
* 404 (one identical body) for a request that does not exist, is not assigned to the caller, is
  of the other type, or (detail only) is no longer pending; 409 when it was decided meanwhile.
"""

import logging

from fastapi import APIRouter, Depends, HTTPException, status
from fastapi.responses import JSONResponse
from sqlalchemy.exc import SQLAlchemyError
from sqlalchemy.orm import Session

from app.auth.dependencies import get_current_user
from app.db.models import User
from app.db.session import get_db
from app.domain.enums import RequestType
from app.schemas.approvals import ApprovalDetail, ApprovalList, DecisionBody, DecisionResponse
from app.services import approvals as service
from app.services.approvals import ApprovalConflict, ApprovalForbidden, ApprovalNotFound

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/approvals", tags=["approvals"])

NOT_FOUND_DETAIL = "Request not found"
CONFLICT_DETAIL = "This request was already decided or is no longer pending approval."
FORBIDDEN_DETAIL = "Only an approver can use the approval queue."


def require_approver(user: User = Depends(get_current_user)) -> User:
    """403 unless the user decides one of the queues (``approves`` is leave or claim)."""
    if user.approves is None:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=FORBIDDEN_DETAIL)
    return user


def _not_found() -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=NOT_FOUND_DETAIL)


def _request_type(value: str) -> RequestType:
    rtype = service.parse_request_type(value)
    if rtype is None:
        raise _not_found()
    return rtype


@router.get("", response_model=ApprovalList)
def list_approvals(
    user: User = Depends(require_approver), db: Session = Depends(get_db)
) -> ApprovalList:
    """The caller's pending requests, oldest submitted first."""
    return service.list_queue(db, user)


@router.get("/{request_type}/{request_id}", response_model=ApprovalDetail)
def approval_detail(
    request_type: str,
    request_id: int,
    user: User = Depends(require_approver),
    db: Session = Depends(get_db),
) -> ApprovalDetail:
    rtype = _request_type(request_type)
    try:
        return service.get_detail(db, user, rtype, request_id)
    except ApprovalNotFound:
        raise _not_found() from None


@router.post("/{request_type}/{request_id}/decision", response_model=DecisionResponse)
def decide(
    request_type: str,
    request_id: int,
    body: DecisionBody,
    user: User = Depends(require_approver),
    db: Session = Depends(get_db),
) -> DecisionResponse | JSONResponse:
    rtype = _request_type(request_type)
    try:
        return service.decide(db, user, rtype, request_id, body.decision, body.note)
    except ApprovalNotFound:
        raise _not_found() from None
    except ApprovalConflict:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=CONFLICT_DETAIL) from None
    except ApprovalForbidden as exc:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=str(exc)) from None
    except SQLAlchemyError:
        logger.exception("Database error while recording a decision")
        return JSONResponse(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            content={"detail": "The database is temporarily unavailable. Please try again."},
        )
